-- A preset contains localized prompts and guides. The catalog RPC only
-- exposes the information needed to choose a question before taking a photo.
CREATE TABLE IF NOT EXISTS public.paper_review_exercises (
  id text PRIMARY KEY CHECK (id ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
  subject text NOT NULL CHECK (subject IN ('physics', 'chemistry', 'biology', 'english', 'french', 'arabic', 'islamic', 'math')),
  chapter_key text NOT NULL CHECK (chapter_key ~ '^[a-z0-9][a-z0-9-]{0,39}$'),
  curriculum text NOT NULL DEFAULT 'shared' CHECK (curriculum IN ('shared', 'arabic', 'distinguished')),
  content jsonb NOT NULL CHECK (
    jsonb_typeof(content) = 'object'
    AND (content ? 'ar' OR content ? 'en')
    AND (NOT (content ? 'ar') OR jsonb_typeof(content -> 'ar') = 'object')
    AND (NOT (content ? 'en') OR jsonb_typeof(content -> 'en') = 'object')
  ),
  source_reference text CHECK (char_length(source_reference) <= 500),
  display_order integer NOT NULL DEFAULT 0 CHECK (display_order >= 0),
  published boolean NOT NULL DEFAULT false,
  CONSTRAINT paper_review_published_content CHECK (NOT published OR (
    (NOT (content ? 'ar') OR (
      jsonb_typeof(content -> 'ar' -> 'title') = 'string' AND char_length(btrim(content -> 'ar' ->> 'title')) BETWEEN 1 AND 100
      AND jsonb_typeof(content -> 'ar' -> 'question') = 'string' AND btrim(content -> 'ar' ->> 'question') <> ''
      AND jsonb_typeof(content -> 'ar' -> 'solution') = 'string' AND btrim(content -> 'ar' ->> 'solution') <> ''
    ) IS TRUE)
    AND (NOT (content ? 'en') OR (
      jsonb_typeof(content -> 'en' -> 'title') = 'string' AND char_length(btrim(content -> 'en' ->> 'title')) BETWEEN 1 AND 100
      AND jsonb_typeof(content -> 'en' -> 'question') = 'string' AND btrim(content -> 'en' ->> 'question') <> ''
      AND jsonb_typeof(content -> 'en' -> 'solution') = 'string' AND btrim(content -> 'en' ->> 'solution') <> ''
    ) IS TRUE)
  ))
);

ALTER TABLE public.paper_review_exercises ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.paper_review_exercises FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.paper_review_exercises TO service_role;

CREATE INDEX IF NOT EXISTS paper_review_exercise_catalog_idx
  ON public.paper_review_exercises (subject, chapter_key, display_order, id) WHERE published;

CREATE OR REPLACE FUNCTION public.paper_review_catalog(
  _subject text, _chapter text, _exercise_id text, _language text
)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  WITH scope AS (
    SELECT e.subject, e.chapter_key
    FROM public.paper_review_exercises e
    WHERE e.id = _exercise_id AND e.published
    UNION ALL
    SELECT _subject, _chapter WHERE _exercise_id IS NULL
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', e.id,
    'subject', e.subject,
    'chapter', e.chapter_key,
    'curriculum', e.curriculum,
    'title', localized.item ->> 'title',
    'question', localized.item ->> 'question'
  ) ORDER BY e.display_order, e.id), '[]'::jsonb)
  FROM scope s
  JOIN public.paper_review_exercises e ON e.subject = s.subject AND e.chapter_key = s.chapter_key AND e.published
  CROSS JOIN LATERAL (
    SELECT COALESCE(e.content -> (CASE WHEN _language = 'en' THEN 'en' ELSE 'ar' END), e.content -> 'ar', e.content -> 'en') AS item
  ) localized;
$$;

CREATE OR REPLACE FUNCTION public.paper_review_exercise_for_review(_exercise_id text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT jsonb_build_object(
    'id', id, 'subject', subject, 'chapter', chapter_key, 'curriculum', curriculum, 'content', content
  )
  FROM public.paper_review_exercises
  WHERE id = _exercise_id AND published;
$$;

REVOKE ALL ON FUNCTION public.paper_review_catalog(text, text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.paper_review_catalog(text, text, text, text) TO authenticated, service_role;
REVOKE ALL ON FUNCTION public.paper_review_exercise_for_review(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.paper_review_exercise_for_review(text) TO service_role;

-- Keep the original exercise IDs so earlier links and saved reviews still resolve.
INSERT INTO public.paper_review_exercises (id, subject, chapter_key, content, display_order, published)
SELECT s.id, s.subject, s.chapter_key, s.content, s.display_order, true
FROM jsonb_to_recordset($paper_exercise_seed$[
  {"id":"distance","subject":"physics","chapter_key":"1","display_order":1,"content":{"ar":{"title":"المسافة بين اللوحين","question":"سعة متسعة ذات لوحين متوازيين تساوي 12 µF. إذا تضاعفت المسافة بين اللوحين مع ثبات المساحة والعازل، فما السعة الجديدة؟","solution":"سلم تدريب · درجتان: درجة لاستخدام العلاقة العكسية C ∝ 1/d مع ثبات المساحة والعازل، ودرجة للناتج 6 µF مع الوحدة.","practice":{"question":"سعة المتسعة 24 µF. إذا صارت المسافة ثلاثة أمثالها وبقيت المساحة والعازل ثابتين، شكد السعة الجديدة؟","choices":["72 µF","8 µF","12 µF"],"correctIndex":1,"explanation":"المسافة صارت 3d، فالسعة صارت ثلث قيمتها: 24 ÷ 3 = 8 µF."}},"en":{"title":"Plate separation","question":"A parallel-plate capacitor has a capacitance of 12 µF. What is its new capacitance when the plate separation doubles and area and dielectric stay fixed?","solution":"Practice key · 2 marks: 1 for the inverse relation C ∝ 1/d at fixed area and dielectric, and 1 for 6 µF with the unit.","practice":{"question":"Capacitance is 24 µF. The separation triples at fixed area and dielectric. What is the new capacitance?","choices":["72 µF","8 µF","12 µF"],"correctIndex":1,"explanation":"With 3d in the denominator, capacitance becomes one-third: 24 ÷ 3 = 8 µF."}}}},
  {"id":"area","subject":"physics","chapter_key":"1","display_order":2,"content":{"ar":{"title":"المساحة المتقابلة","question":"متسعة سعتها 8 µF. أصبحت المساحة المتقابلة للوحين مرة ونصف مساحتها الأصلية، مع ثبات المسافة والعازل. احسب السعة الجديدة.","solution":"سلم تدريب · درجتان: درجة للعلاقة الطردية C ∝ A، ودرجة للتعويض الصحيح 8 × 1.5 = 12 µF.","practice":{"question":"إذا كانت السعة 6 µF وتضاعفت المساحة المتقابلة للوحين وبقي كلشي ثاني ثابت، شكد تصير؟","choices":["3 µF","6 µF","12 µF"],"correctIndex":2,"explanation":"المساحة بالبسط. إذا تضاعفت المساحة وحدها، تتضاعف السعة: 6 × 2 = 12 µF."}},"en":{"title":"Overlapping plate area","question":"A capacitor has capacitance 8 µF. Its overlapping plate area increases to 1.5 times the original at fixed separation and dielectric. Find the new capacitance.","solution":"Practice key · 2 marks: 1 for the direct relation C ∝ A and 1 for 8 × 1.5 = 12 µF.","practice":{"question":"What happens to a 6 µF capacitance if the overlapping area doubles with the other variables fixed?","choices":["3 µF","6 µF","12 µF"],"correctIndex":2,"explanation":"Area is in the numerator, so doubling it doubles the capacitance to 12 µF."}}}},
  {"id":"dielectric","subject":"physics","chapter_key":"1","display_order":3,"content":{"ar":{"title":"إدخال العازل","question":"متسعة هوائية سعتها 4 µF. ملأ عازل ثابت عزله النسبي 3 الفراغ بين لوحيها تماماً. احسب سعتها بعد إدخال العازل.","solution":"سلم تدريب · درجتان: درجة لكتابة C₂ = κC₁ عند امتلاء الفراغ بالعازل، ودرجة للناتج 12 µF.","practice":{"question":"متسعة هوائية 5 µF. عازل ثابت عزله 4 ملأ كل الفراغ بين اللوحين. شكد تصير السعة؟","choices":["20 µF","1.25 µF","9 µF"],"correctIndex":0,"explanation":"نضرب السعة الهوائية بثابت العزل لأن العازل ملأ الفراغ كله: 5 × 4 = 20 µF."}},"en":{"title":"Inserting a dielectric","question":"An air capacitor has capacitance 4 µF. A dielectric of relative permittivity 3 completely fills the gap. Find the new capacitance.","solution":"Practice key · 2 marks: 1 for C₂ = κC₁ when the dielectric fills the gap, and 1 for 12 µF.","practice":{"question":"The air capacitance is 5 µF and a dielectric with κ = 4 fills the gap. What is the new capacitance?","choices":["20 µF","1.25 µF","9 µF"],"correctIndex":0,"explanation":"The dielectric fills the gap, so multiply the air capacitance by κ: 5 × 4 = 20 µF."}}}},
  {"id":"units","subject":"physics","chapter_key":"1","display_order":4,"content":{"ar":{"title":"تحويل وحدات السعة","question":"حوّل سعة مقدارها 5 µF إلى الفاراد.","solution":"سلم تدريب · درجتان: درجة لإدراك أن المايكرو يساوي 10⁻⁶، ودرجة لكتابة 5 × 10⁻⁶ F.","practice":{"question":"حوّل 8 µF إلى الفاراد.","choices":["8 × 10⁻³ F","8 × 10⁻⁶ F","8 × 10⁶ F"],"correctIndex":1,"explanation":"الرمز µ يعني جزءاً من مليون، فـ 8 µF تساوي 8 × 10⁻⁶ F."}},"en":{"title":"Capacitance units","question":"Convert a capacitance of 5 µF to farads.","solution":"Practice key · 2 marks: 1 for the micro prefix 10⁻⁶ and 1 for 5 × 10⁻⁶ F.","practice":{"question":"Convert 8 µF to farads.","choices":["8 × 10⁻³ F","8 × 10⁻⁶ F","8 × 10⁶ F"],"correctIndex":1,"explanation":"The prefix micro means one millionth, so 8 µF equals 8 × 10⁻⁶ F."}}}},
  {"id":"formula","subject":"physics","chapter_key":"1","display_order":5,"content":{"ar":{"title":"التعويض بقانون السعة","question":"سماحية العازل ε = 4 × 10⁻¹¹ F/m، ومساحة اللوح A = 0.02 m² والمسافة d = 0.004 m. احسب سعة المتسعة ذات اللوحين.","solution":"سلم تدريب · درجتان: درجة للتعويض في C = εA/d، ودرجة للناتج بوحدته 2 × 10⁻¹⁰ F.","practice":{"question":"إذا كانت ε = 5 × 10⁻¹¹ F/m، وكانت A = 0.03 m² وd = 0.005 m، شكد C؟","choices":["3 × 10⁻⁹ F","3 × 10⁻¹² F","3 × 10⁻¹⁰ F"],"correctIndex":2,"explanation":"نقسم A على d فنحصل على 6، ثم نضرب بسماحية العازل: 6 × 5 × 10⁻¹¹ = 3 × 10⁻¹⁰ F."}},"en":{"title":"Using the capacitance formula","question":"A parallel-plate capacitor has ε = 4 × 10⁻¹¹ F/m, A = 0.02 m², and d = 0.004 m. Find its capacitance.","solution":"Practice key · 2 marks: 1 for substitution into C = εA/d and 1 for 2 × 10⁻¹⁰ F with the unit.","practice":{"question":"Find C when ε = 5 × 10⁻¹¹ F/m, A = 0.03 m², and d = 0.005 m.","choices":["3 × 10⁻⁹ F","3 × 10⁻¹² F","3 × 10⁻¹⁰ F"],"correctIndex":2,"explanation":"A/d = 6. Multiply by the permittivity: 6 × 5 × 10⁻¹¹ = 3 × 10⁻¹⁰ F."}}}},
  {"id":"ch2-faraday","subject":"physics","chapter_key":"2","display_order":1,"content":{"ar":{"title":"قانون فاراداي","question":"ملف من 100 لفة. تغيّر الفيض خلال كل لفة من 0.020 Wb إلى 0.008 Wb خلال 0.40 s. احسب مقدار القوة الدافعة الحثية المتوسطة.","solution":"درجة لإيجاد مقدار تغيّر الفيض 0.012 Wb. درجة لاستخدام |ε| = N|ΔΦ|/Δt وإيجاد 3 V.","practice":{"question":"ملف من 80 لفة. نقص الفيض خلال كل لفة من 0.016 Wb إلى 0.004 Wb خلال 0.30 s. ما مقدار القوة الدافعة الحثية المتوسطة؟","choices":["0.04 V","3.2 V","0.96 V"],"correctIndex":1,"explanation":"نضرب تغيّر الفيض بكل لفة بعدد اللفات ونقسم على الزمن. 80 × (0.016 − 0.004) ÷ 0.30 = 3.2 V."}},"en":{"title":"Faraday’s law","question":"The magnetic flux per turn of a 100-turn coil drops from 0.020 Wb to 0.008 Wb in 0.40 s. Find the magnitude of the average induced emf.","solution":"One mark for the flux change magnitude of 0.012 Wb. One for using |ε| = N|ΔΦ|/Δt to get 3 V.","practice":{"question":"Flux per turn through an 80-turn coil falls from 0.016 Wb to 0.004 Wb in 0.30 s. What is the magnitude of the average induced emf?","choices":["0.04 V","3.2 V","0.96 V"],"correctIndex":1,"explanation":"Multiply the flux change per turn by the turns, then divide by time. 80 × (0.016 − 0.004) ÷ 0.30 = 3.2 V."}}}},
  {"id":"ch2-lenz","subject":"physics","chapter_key":"2","display_order":2,"content":{"ar":{"title":"اتجاه التيار بقانون لنز","question":"حلقة مغلقة بمستوى الورقة، ومجال مغناطيسي خارجي داخل إلى الورقة يزداد. بأي اتجاه يسري التيار الحثي كما تراه وأنت تنظر للورقة؟","solution":"درجة لأن المجال الحثي يتجه خارج الورقة لمعارضة الزيادة. درجة لاستنتاج اتجاه التيار عكس عقارب الساعة بقاعدة اليد اليمنى.","practice":{"question":"إذا صار المجال الخارجي الداخل للورقة يتناقص، بأي اتجاه يسري التيار الحثي وأنت تنظر لنفس الوجه من الحلقة؟","choices":["عكس عقارب الساعة","مع عقارب الساعة","ما يتولّد تيار"],"correctIndex":1,"explanation":"المجال الحثي يكون داخل للورقة حتى يقاوم نقصان الفيض. قاعدة اليد اليمنى تنطي اتجاه مع عقارب الساعة."}},"en":{"title":"Current direction and Lenz’s law","question":"A closed loop lies in the page. An external magnetic field into the page is increasing. Which way does induced current flow as you face the page?","solution":"One mark for an induced field out of the page to oppose the increase. One for using the right-hand rule to get counterclockwise current.","practice":{"question":"If the external field into the page now decreases, which way does current flow when viewed from the same side of the loop?","choices":["Counterclockwise","Clockwise","No current flows"],"correctIndex":1,"explanation":"The induced field points into the page to oppose the loss of flux. The right-hand rule gives clockwise current."}}}},
  {"id":"ch2-motional-emf","subject":"physics","chapter_key":"2","display_order":3,"content":{"ar":{"title":"القوة الدافعة الحركية","question":"قضيب موصل طوله 0.40 m يتحرك بسرعة 6 m/s في مجال مغناطيسي كثافته 0.25 T. إذا كان القضيب والسرعة والمجال متعامدة اثنين اثنين، احسب القوة الدافعة بين طرفيه.","solution":"درجة لاختيار العلاقة ε = Bℓv للتعامد. درجة للتعويض 0.25 × 0.40 × 6 = 0.60 V.","practice":{"question":"قضيب طوله 0.20 m يتحرك بسرعة 8 m/s في مجال 0.50 T بنفس وضع التعامد. شكد القوة الدافعة بين طرفيه؟","choices":["0.10 V","4.0 V","0.80 V"],"correctIndex":2,"explanation":"هنا نضرب كثافة المجال بطول القضيب وبسرعته. 0.50 × 0.20 × 8 = 0.80 V."}},"en":{"title":"Motional emf","question":"A 0.40 m conducting rod moves at 6 m/s in a 0.25 T field. The rod, velocity, and field are mutually perpendicular. Find the emf across its ends.","solution":"One mark for choosing ε = Bℓv in the perpendicular geometry. One for 0.25 × 0.40 × 6 = 0.60 V.","practice":{"question":"A 0.20 m rod moves at 8 m/s in a 0.50 T field with the same perpendicular geometry. What is the emf?","choices":["0.10 V","4.0 V","0.80 V"],"correctIndex":2,"explanation":"Multiply the field strength, rod length, and speed. 0.50 × 0.20 × 8 = 0.80 V."}}}},
  {"id":"ch2-transformer","subject":"physics","chapter_key":"2","display_order":4,"content":{"ar":{"title":"نسبة الجهد في المحوّلة","question":"محوّلة مثالية عدد لفات ملفها الابتدائي 600 والثانوي 150. الجهد المتناوب الفعّال للابتدائي 120 V. احسب الجهد الفعّال للثانوي.","solution":"درجة لكتابة Vₛ/Vₚ = Nₛ/Nₚ. درجة لاستخدام نسبة 150/600 وإيجاد 30 V.","practice":{"question":"محوّلة مثالية ابتدائيها 500 لفة وثانويها 100 لفة. إذا كان الجهد الفعّال للابتدائي 200 V، شكد الجهد الفعّال للثانوي؟","choices":["40 V","1,000 V","50 V"],"correctIndex":0,"explanation":"نضرب جهد الابتدائي بنسبة لفات الثانوي إلى الابتدائي. 200 × (100/500) = 40 V."}},"en":{"title":"Transformer voltage ratio","question":"An ideal transformer has 600 primary turns and 150 secondary turns. The primary RMS voltage is 120 V. Find the secondary RMS voltage.","solution":"One mark for Vₛ/Vₚ = Nₛ/Nₚ. One for using 150/600 to obtain 30 V.","practice":{"question":"An ideal transformer has 500 primary turns and 100 secondary turns. Its primary RMS voltage is 200 V. What is the secondary RMS voltage?","choices":["40 V","1,000 V","50 V"],"correctIndex":0,"explanation":"Multiply the primary voltage by the secondary-to-primary turns ratio. 200 × (100/500) = 40 V."}}}},
  {"id":"ch2-self-induction","subject":"physics","chapter_key":"2","display_order":5,"content":{"ar":{"title":"الحث الذاتي للمحث","question":"محث معامل حثه الذاتي 0.40 H. تزايد التيار فيه بانتظام من 1 A إلى 5 A خلال 0.20 s. احسب مقدار القوة الدافعة للحث الذاتي.","solution":"درجة لإيجاد معدّل تغيّر التيار 20 A/s. درجة لتطبيق |ε| = L|ΔI|/Δt والحصول على 8 V.","practice":{"question":"محث 0.25 H، نزل التيار فيه بانتظام من 6 A إلى 2 A خلال 0.50 s. ما مقدار القوة الدافعة للحث الذاتي؟","choices":["0.50 V","8 V","2 V"],"correctIndex":2,"explanation":"مقدار التغيّر 4 A ومعدّله 8 A/s. نضرب المعدّل في 0.25 H ونحصل على 2 V."}},"en":{"title":"Self-induced emf","question":"Current through a 0.40 H inductor rises uniformly from 1 A to 5 A in 0.20 s. Find the magnitude of the self-induced emf.","solution":"One mark for the current change rate of 20 A/s. One for |ε| = L|ΔI|/Δt and 8 V.","practice":{"question":"The current in a 0.25 H inductor falls uniformly from 6 A to 2 A in 0.50 s. What is the magnitude of the self-induced emf?","choices":["0.50 V","8 V","2 V"],"correctIndex":2,"explanation":"The current changes by 4 A at a rate of 8 A/s. Multiply by 0.25 H to obtain 2 V."}}}},
  {"id":"ch3-rms","subject":"physics","chapter_key":"3","display_order":1,"content":{"ar":{"title":"القيمة الفعّالة","question":"جهد متناوب جيبي قيمته العظمى 24√2 V. احسب قيمته الفعّالة.","solution":"درجة لاستخدام Vᵣₘₛ = Vₘ/√2 للموجة الجيبية. درجة لإيجاد 24 V.","practice":{"question":"تيار متناوب جيبي قيمته العظمى 4√2 A. شكد قيمته الفعّالة؟","choices":["8 A","2 A","4 A"],"correctIndex":2,"explanation":"نقسم القيمة العظمى للتيار الجيبي على √2 ونحصل على 4 A."}},"en":{"title":"Effective (RMS) value","question":"A sinusoidal voltage has a peak value of 24√2 V. Find its RMS value.","solution":"One mark for using Vᵣₘₛ = Vₘ/√2 for a sine wave. One for 24 V.","practice":{"question":"A sinusoidal current has a peak of 4√2 A. What is its RMS value?","choices":["8 A","2 A","4 A"],"correctIndex":2,"explanation":"Divide the peak sinusoidal current by √2 to obtain 4 A."}}}},
  {"id":"ch3-inductive-reactance","subject":"physics","chapter_key":"3","display_order":2,"content":{"ar":{"title":"الرادّة الحثية","question":"محث مثالي حثه 0.30 H موصول بمصدر متناوب تردده الزاوي 100 rad/s. احسب الرادّة الحثية.","solution":"درجة لكتابة X_L = ωL. درجة للتعويض 100 × 0.30 والحصول على 30 Ω.","practice":{"question":"محث 0.20 H بمصدر متناوب تردده الزاوي 200 rad/s. شكد رادّته الحثية؟","choices":["40 Ω","1,000 Ω","20 Ω"],"correctIndex":0,"explanation":"التردد الزاوي معطى مباشرة. نضرب 200 × 0.20 = 40 Ω."}},"en":{"title":"Inductive reactance","question":"An ideal inductor of 0.30 H is connected to an AC source with angular frequency 100 rad/s. Find its inductive reactance.","solution":"One mark for X_L = ωL. One for 100 × 0.30 = 30 Ω.","practice":{"question":"A 0.20 H inductor is connected at 200 rad/s. What is its inductive reactance?","choices":["40 Ω","1,000 Ω","20 Ω"],"correctIndex":0,"explanation":"The angular frequency is already given. Multiply 200 × 0.20 to get 40 Ω."}}}},
  {"id":"ch3-capacitive-reactance","subject":"physics","chapter_key":"3","display_order":3,"content":{"ar":{"title":"الرادّة السعوية","question":"متسعة 20 µF في دائرة متناوبة ترددها الزاوي 1,000 rad/s. احسب الرادّة السعوية.","solution":"درجة لتحويل السعة إلى 20 × 10⁻⁶ F. درجة لتطبيق X_C = 1/(ωC) وإيجاد 50 Ω.","practice":{"question":"متسعة 50 µF تعمل بتردد زاوي 500 rad/s. شكد الرادّة السعوية؟","choices":["25 Ω","40 Ω","0.025 Ω"],"correctIndex":1,"explanation":"بعد تحويل السعة إلى الفاراد يصير ωC = 0.025. مقلوبه يساوي 40 Ω."}},"en":{"title":"Capacitive reactance","question":"A 20 µF capacitor is in an AC circuit at 1,000 rad/s. Find its capacitive reactance.","solution":"One mark for converting to 20 × 10⁻⁶ F. One for X_C = 1/(ωC) and 50 Ω.","practice":{"question":"A 50 µF capacitor operates at 500 rad/s. What is its capacitive reactance?","choices":["25 Ω","40 Ω","0.025 Ω"],"correctIndex":1,"explanation":"After converting capacitance to farads, ωC = 0.025. Its reciprocal is 40 Ω."}}}},
  {"id":"ch3-series-impedance","subject":"physics","chapter_key":"3","display_order":4,"content":{"ar":{"title":"الممانعة في دائرة RLC","question":"دائرة RLC على التوالي فيها R = 30 Ω وX_L = 60 Ω وX_C = 20 Ω. احسب مقدار الممانعة.","solution":"درجة لإيجاد صافي الرادّة 40 Ω. درجة لتطبيق Z = √(R² + (X_L − X_C)²) وإيجاد 50 Ω.","practice":{"question":"بدائرة RLC على التوالي، R = 6 Ω وX_L = 15 Ω وX_C = 7 Ω. شكد مقدار الممانعة؟","choices":["10 Ω","14 Ω","28 Ω"],"correctIndex":0,"explanation":"نطرح الرادّتين أولاً فنحصل على 8 Ω. مقدار الممانعة √(6² + 8²) = 10 Ω."}},"en":{"title":"Series RLC impedance","question":"A series RLC circuit has R = 30 Ω, X_L = 60 Ω, and X_C = 20 Ω. Find the magnitude of its impedance.","solution":"One mark for the net reactance of 40 Ω. One for Z = √(R² + (X_L − X_C)²) and 50 Ω.","practice":{"question":"In a series RLC circuit, R = 6 Ω, X_L = 15 Ω, and X_C = 7 Ω. What is the magnitude of the impedance?","choices":["10 Ω","14 Ω","28 Ω"],"correctIndex":0,"explanation":"Subtract the reactances first to get 8 Ω. The impedance magnitude is √(6² + 8²) = 10 Ω."}}}},
  {"id":"ch3-resonance","subject":"physics","chapter_key":"3","display_order":5,"content":{"ar":{"title":"التردد الزاوي للرنين","question":"بدائرة RLC على التوالي، الحث 0.10 H والسعة 10 µF. احسب التردد الزاوي عند الرنين.","solution":"درجة لإيجاد LC = 10⁻⁶ بعد تحويل السعة إلى الفاراد. درجة لاستخدام ω₀ = 1/√(LC) وإيجاد 1,000 rad/s.","practice":{"question":"إذا صار الحث 0.20 H والسعة 20 µF، شكد يصير التردد الزاوي للرنين؟","choices":["250 rad/s","1,000 rad/s","500 rad/s"],"correctIndex":2,"explanation":"LC = 4 × 10⁻⁶، وجذره 0.002. ناخذ مقلوبه حتى نحصل على 500 rad/s."}},"en":{"title":"Angular resonance frequency","question":"In a series RLC circuit, L = 0.10 H and C = 10 µF. Find its angular resonance frequency.","solution":"One mark for LC = 10⁻⁶ after converting capacitance to farads. One for ω₀ = 1/√(LC) and 1,000 rad/s.","practice":{"question":"With L = 0.20 H and C = 20 µF, what is the angular resonance frequency?","choices":["250 rad/s","1,000 rad/s","500 rad/s"],"correctIndex":2,"explanation":"LC = 4 × 10⁻⁶ and its square root is 0.002. Taking the reciprocal gives 500 rad/s."}}}},
  {"id":"ch4-wavelength","subject":"physics","chapter_key":"4","display_order":1,"content":{"ar":{"title":"الطول الموجي لموجة الراديو","question":"موجة راديو ترددها 100 MHz تنتشر في الفراغ بسرعة 3 × 10⁸ m/s. احسب طولها الموجي.","solution":"درجة لتحويل التردد إلى 10⁸ Hz. درجة لتطبيق λ = c/f والحصول على 3 m.","practice":{"question":"موجة ترددها 150 MHz في الفراغ. باستخدام c = 3 × 10⁸ m/s، شكد طولها الموجي؟","choices":["0.5 m","4.5 m","2 m"],"correctIndex":2,"explanation":"نحوّل 150 MHz إلى 1.5 × 10⁸ Hz. نقسم سرعة الضوء على التردد فيطلع 2 m."}},"en":{"title":"Radio wavelength","question":"A 100 MHz radio wave travels through vacuum at 3 × 10⁸ m/s. Find its wavelength.","solution":"One mark for converting frequency to 10⁸ Hz. One for λ = c/f and 3 m.","practice":{"question":"What is the wavelength of a 150 MHz wave in vacuum? Use c = 3 × 10⁸ m/s.","choices":["0.5 m","4.5 m","2 m"],"correctIndex":2,"explanation":"Convert 150 MHz to 1.5 × 10⁸ Hz. Dividing the wave speed by that frequency gives 2 m."}}}},
  {"id":"ch4-field-directions","subject":"physics","chapter_key":"4","display_order":2,"content":{"ar":{"title":"اتجاه المجالين والانتشار","question":"ليش الموجة الكهرومغناطيسية مستعرضة؟ وضّح اتجاه اهتزاز المجالين الكهربائي والمغناطيسي بالنسبة لاتجاه انتشارها وبالنسبة لبعضهما.","solution":"درجة لأن اهتزاز كل مجال عمودي على اتجاه الانتشار. درجة لأن المجالين الكهربائي والمغناطيسي متعامدان.","practice":{"question":"موجة كهرومغناطيسية مستوية تنتشر على محور x ومجالها الكهربائي يهتز على محور y. على أي محور يهتز المجال المغناطيسي؟","choices":["x","z","y"],"correctIndex":1,"explanation":"المجال المغناطيسي لازم يكون عمودي على x وعلى y، فمحور اهتزازه z."}},"en":{"title":"Fields and propagation","question":"Why is an electromagnetic wave transverse? Describe how the electric and magnetic fields are oriented relative to propagation and to each other.","solution":"One mark for both fields being perpendicular to propagation. One for the fields being perpendicular to each other.","practice":{"question":"A plane electromagnetic wave travels along the x-axis and its electric field oscillates along the y-axis. Along which axis does its magnetic field oscillate?","choices":["x","z","y"],"correctIndex":1,"explanation":"The magnetic field must be perpendicular to both x and y, so its oscillation axis is z."}}}},
  {"id":"ch4-antenna","subject":"physics","chapter_key":"4","display_order":3,"content":{"ar":{"title":"طول الهوائي","question":"هوائي نصف موجة مصمم لإشارة راديوية طولها الموجي 4 m. احسب الطول الكلي للهوائي في النموذج المثالي.","solution":"درجة لاختيار العلاقة L = λ/2. درجة للناتج 2 m.","practice":{"question":"إذا كان طول الموجة 6 m، شكد طول الهوائي المثالي إذا كان من نوع ربع الموجة؟","choices":["1.5 m","3 m","6 m"],"correctIndex":0,"explanation":"هوائي ربع الموجة طوله λ/4. هنا نقسم 6 على 4 فيطلع 1.5 m."}},"en":{"title":"Antenna length","question":"An ideal half-wave antenna is designed for a radio signal with a 4 m wavelength. Find the total antenna length.","solution":"One mark for L = λ/2. One for 2 m.","practice":{"question":"For a 6 m wavelength, how long is an ideal quarter-wave antenna?","choices":["1.5 m","3 m","6 m"],"correctIndex":0,"explanation":"The antenna is a quarter wavelength long. Divide 6 by 4 to obtain 1.5 m."}}}},
  {"id":"ch4-modulation","subject":"physics","chapter_key":"4","display_order":4,"content":{"ar":{"title":"التضمين AM وFM","question":"في تضمين السعة (AM)، أي خاصية في الموجة الحاملة تتغيّر لتتبع إشارة المعلومات؟","solution":"المطلوب تحديد سعة الموجة الحاملة. تتغيّر سعتها بما يتوافق مع الإشارة المراد إرسالها.","practice":{"question":"عند استخدام تضمين التردد (FM)، أي خاصية من خصائص الحاملة تتغيّر مع إشارة المعلومات؟","choices":["السعة","التردد اللحظي","سرعة الانتشار في الفراغ"],"correctIndex":1,"explanation":"في FM يتغيّر التردد اللحظي للحاملة حول ترددها المركزي حسب إشارة المعلومات."}},"en":{"title":"AM and FM modulation","question":"In amplitude modulation (AM), which property of the carrier changes to follow the information signal?","solution":"Identify the carrier amplitude. It varies in response to the information signal.","practice":{"question":"In frequency modulation (FM), which carrier property varies with the information signal?","choices":["Amplitude","Instantaneous frequency","Propagation speed in vacuum"],"correctIndex":1,"explanation":"In FM the carrier’s instantaneous frequency shifts around its center frequency with the information signal."}}}},
  {"id":"ch4-radio-tuning","subject":"physics","chapter_key":"4","display_order":5,"content":{"ar":{"title":"ضبط دائرة الاستقبال","question":"صارت السعة في دائرة ضبط LC أربعة أمثال قيمتها الأصلية وبقي الحث ثابتاً. كيف يتغيّر تردد الرنين؟","solution":"درجة لكتابة f = 1/(2π√(LC)). درجة لاستنتاج أن التردد يصير نصف قيمته لأن √4 = 2.","practice":{"question":"إذا صار حث ملف دائرة الضبط تسعة أمثال قيمته وبقيت السعة ثابتة، شكد يصير تردد الرنين مقارنة بالأصلي؟","choices":["تسعة أمثاله","تُسع قيمته","ثلث قيمته"],"correctIndex":2,"explanation":"الحث تحت الجذر بالمقام. إذا صار 9L، المقام يصير ثلاثة أمثاله والتردد يصير ثلثه."}},"en":{"title":"Tuning a radio receiver","question":"A student increases the capacitance in an LC tuning circuit to four times its original value at fixed inductance. What happens to the resonant frequency?","solution":"One mark for f = 1/(2π√(LC)). One for halving the frequency because √4 = 2.","practice":{"question":"Inductance becomes nine times its original value and capacitance is fixed. What is the new tuning frequency relative to the original?","choices":["Nine times as high","One ninth as high","One third as high"],"correctIndex":2,"explanation":"Inductance is under a square root in the denominator. Replacing L by 9L triples the denominator and reduces the frequency to one third."}}}},
  {"id":"ch5-young-fringes","subject":"physics","chapter_key":"5","display_order":1,"content":{"ar":{"title":"المسافة بين أهداب يونك","question":"بتجربة شقي يونك، المسافة بين الشقين 0.50 mm، والشاشة تبعد 2.0 m، والطول الموجي 600 nm. احسب المسافة بين هدبين مضيئين متجاورين قرب مركز الشاشة.","solution":"درجة لتحويل d وλ إلى المتر. درجة لتطبيق Δy = λD/d وإيجاد 2.4 mm.","practice":{"question":"إذا كان الطول الموجي 500 nm، وبعد الشاشة 1.5 m، والمسافة بين الشقين 0.25 mm، شكد المسافة بين هدبين مضيئين متجاورين قرب المركز؟","choices":["0.30 mm","3.0 mm","0.75 mm"],"correctIndex":1,"explanation":"بالتعويض بالمتر، Δy = (5 × 10⁻⁷ × 1.5)/(2.5 × 10⁻⁴) = 0.003 m، يعني 3.0 mm."}},"en":{"title":"Young’s fringe spacing","question":"In Young’s experiment, the slits are 0.50 mm apart, the screen is 2.0 m away, and wavelength is 600 nm. Find the spacing between adjacent bright fringes near the center.","solution":"One mark for converting d and λ to meters. One for Δy = λD/d and 2.4 mm.","practice":{"question":"For 500 nm light, screen distance 1.5 m, and slit separation 0.25 mm, what is the spacing between adjacent bright fringes near the center?","choices":["0.30 mm","3.0 mm","0.75 mm"],"correctIndex":1,"explanation":"Using meters, Δy = (5 × 10⁻⁷ × 1.5)/(2.5 × 10⁻⁴) = 0.003 m, or 3.0 mm."}}}},
  {"id":"ch5-path-difference","subject":"physics","chapter_key":"5","display_order":2,"content":{"ar":{"title":"فرق المسير ونوع التداخل","question":"في تجربة شقي يونك بشقين متماثلين وموجتين متفقتين بالطور عند الشقين، وصل الضوء إلى نقطة بفرق مسير 3λ/2. حدّد نوع التداخل عندها.","solution":"درجة للتعرّف أن فرق المسير مضاعف فردي لنصف طول موجي. درجة لتحديد تداخل هدّام.","practice":{"question":"إذا كان فرق المسير عند نقطة ثانية يساوي 2λ في نفس التجربة، شنو نوع التداخل؟","choices":["هدّام","ماكو تداخل","بنّاء"],"correctIndex":2,"explanation":"فرق المسير 2λ مضاعف صحيح لطول موجي كامل. الموجتان توصلان بنفس الطور ويصير تداخل بنّاء."}},"en":{"title":"Path difference and interference","question":"In Young’s experiment with identical slits and waves in phase at the slits, the light reaches a point with path difference 3λ/2. Identify the type of interference there.","solution":"One mark for recognizing an odd multiple of half a wavelength. One for identifying destructive interference.","practice":{"question":"In the same experiment, the path difference at another point is 2λ. What type of interference occurs?","choices":["Destructive","No interference","Constructive"],"correctIndex":2,"explanation":"A path difference of 2λ is a whole number of wavelengths. The waves arrive in phase and interfere constructively."}}}},
  {"id":"ch5-diffraction-grating","subject":"physics","chapter_key":"5","display_order":3,"content":{"ar":{"title":"محزّز الحيود","question":"يسقط ضوء طوله الموجي 500 nm عمودياً على محزّز المسافة بين شقوقه 2.0 µm. احسب جيب زاوية الهدب المضيء من الرتبة الأولى.","solution":"درجة لكتابة d sin θ = mλ وتوحيد وحدات d وλ. درجة لإيجاد sin θ = 0.25.","practice":{"question":"يسقط ضوء 500 nm عمودياً على محزّز مسافة شقوقه 2.5 µm. شكد sin θ للرتبة الثانية؟","choices":["0.20","0.40","0.80"],"correctIndex":1,"explanation":"500 nm تساوي 0.50 µm. للرتبة الثانية، sin θ = 2 × 0.50 ÷ 2.5 = 0.40."}},"en":{"title":"Diffraction grating","question":"Light of wavelength 500 nm is incident normally on a grating with 2.0 µm spacing. Find the sine of the angle of the first-order bright fringe.","solution":"One mark for d sin θ = mλ and consistent length units. One for sin θ = 0.25.","practice":{"question":"Light of 500 nm is incident normally on a grating with 2.5 µm spacing. What is sin θ for the second order?","choices":["0.20","0.40","0.80"],"correctIndex":1,"explanation":"500 nm equals 0.50 µm. In second order, sin θ = 2 × 0.50 ÷ 2.5 = 0.40."}}}},
  {"id":"ch5-single-slit","subject":"physics","chapter_key":"5","display_order":4,"content":{"ar":{"title":"عرض الهدب المركزي في حيود الشق المفرد","question":"في حيود الشق المفرد وعند الزوايا الصغيرة، شلون يتغيّر عرض الهدب المركزي على الشاشة إذا نقص عرض الشق إلى النصف، والطول الموجي وبعد الشاشة ثابتان؟","solution":"درجة لبيان أن عرض الهدب المركزي يقارب 2λD/a. درجة لاستنتاج أنه يتضاعف إذا صار عرض الشق a/2.","practice":{"question":"إذا صار عرض الشق ثلاثة أمثال قيمته عند الزوايا الصغيرة، شكد يصير عرض الهدب المركزي مع ثبات بقية المعطيات؟","choices":["ثلث قيمته","ثلاثة أمثاله","نفس قيمته"],"correctIndex":0,"explanation":"عرض الشق بالمقام في العلاقة التقريبية 2λD/a. من يزيد a للثلاثة، العرض يصير ثلثه."}},"en":{"title":"Central fringe in single-slit diffraction","question":"In single-slit diffraction at small angles, what happens to the central fringe width on the screen when the slit width halves at fixed wavelength and screen distance?","solution":"One mark for the approximate central width 2λD/a. One for doubling the width when the slit becomes a/2.","practice":{"question":"At small angles, what happens to the central fringe width if the slit becomes three times as wide with all else fixed?","choices":["One third as wide","Three times as wide","The same width"],"correctIndex":0,"explanation":"Slit width is in the denominator of 2λD/a. Tripling a reduces the fringe width to one third."}}}},
  {"id":"ch5-brewster","subject":"physics","chapter_key":"5","display_order":5,"content":{"ar":{"title":"زاوية بروستر","question":"يسقط الضوء من الهواء على وسط شفاف ويصير الشعاع المنعكس مستقطباً كلياً عند زاوية سقوط θ. إذا كان tan θ = 1.50، احسب معامل انكسار الوسط بالنسبة للهواء.","solution":"درجة لتحديد أن θ زاوية بروستر. درجة لتطبيق n = tan θ وإيجاد 1.50.","practice":{"question":"عند السقوط بزاوية بروستر، شكد تكون الزاوية بين الشعاع المنعكس والمنكسر؟","choices":["45°","180°","90°"],"correctIndex":2,"explanation":"عند زاوية بروستر، الشعاع المنعكس والمنكسر متعامدان. الزاوية بينهما 90°."}},"en":{"title":"Brewster’s angle","question":"Light is incident from air onto a transparent medium. At incidence angle θ the reflected ray is completely polarized. Given tan θ = 1.50, find the medium’s refractive index relative to air.","solution":"One mark for identifying θ as Brewster’s angle. One for using n = tan θ to get 1.50.","practice":{"question":"At Brewster’s angle, what is the angle between the reflected and refracted rays?","choices":["45°","180°","90°"],"correctIndex":2,"explanation":"At Brewster’s angle the reflected and refracted rays are perpendicular. Their angle is 90°."}}}},
  {"id":"ch6-photon-energy","subject":"physics","chapter_key":"6","display_order":1,"content":{"ar":{"title":"طاقة الفوتون","question":"فوتون تردده 5 × 10¹⁴ Hz. احسب طاقته باستعمال ثابت بلانك h = 6.6 × 10⁻³⁴ J·s.","solution":"درجة لاختيار E = hf. درجة للتعويض وإيجاد 3.3 × 10⁻¹⁹ J.","practice":{"question":"شكد طاقة فوتون تردده 6 × 10¹⁴ Hz إذا استعملنا h = 6.6 × 10⁻³⁴ J·s؟","choices":["3.96 × 10⁻¹⁹ J","3.96 × 10⁻²⁰ J","1.10 × 10⁻⁴⁸ J"],"correctIndex":0,"explanation":"نضرب h في f. الناتج 39.6 × 10⁻²⁰ J، ونكتبه بالصيغة العلمية 3.96 × 10⁻¹⁹ J."}},"en":{"title":"Photon energy","question":"A photon has frequency 5 × 10¹⁴ Hz. Find its energy using Planck’s constant h = 6.6 × 10⁻³⁴ J·s.","solution":"One mark for E = hf. One for substituting to obtain 3.3 × 10⁻¹⁹ J.","practice":{"question":"What is the energy of a 6 × 10¹⁴ Hz photon? Use h = 6.6 × 10⁻³⁴ J·s.","choices":["3.96 × 10⁻¹⁹ J","3.96 × 10⁻²⁰ J","1.10 × 10⁻⁴⁸ J"],"correctIndex":0,"explanation":"Multiply h by f to get 39.6 × 10⁻²⁰ J, or 3.96 × 10⁻¹⁹ J in scientific notation."}}}},
  {"id":"ch6-photoelectric","subject":"physics","chapter_key":"6","display_order":2,"content":{"ar":{"title":"أقصى طاقة حركية للإلكترون","question":"سقط فوتون طاقته 5.0 eV على سطح فلز دالة شغله 2.2 eV. احسب أقصى طاقة حركية للإلكترون المنبعث.","solution":"درجة لكتابة K_max = E − φ. درجة لإيجاد 2.8 eV.","practice":{"question":"إذا كانت طاقة الفوتون 6.1 eV ودالة شغل الفلز 2.6 eV، شكد أقصى طاقة حركية؟","choices":["8.7 eV","3.5 eV","2.6 eV"],"correctIndex":1,"explanation":"نطرح طاقة تحرير الإلكترون من طاقة الفوتون. الباقي 6.1 − 2.6 = 3.5 eV."}},"en":{"title":"Maximum photoelectron energy","question":"A photon of energy 5.0 eV hits a metal with work function 2.2 eV. Find the maximum kinetic energy of an emitted electron.","solution":"One mark for K_max = E − φ. One for 2.8 eV.","practice":{"question":"The photon energy is 6.1 eV and the work function is 2.6 eV. What is the maximum kinetic energy?","choices":["8.7 eV","3.5 eV","2.6 eV"],"correctIndex":1,"explanation":"Subtract the energy needed to free the electron from the photon energy. The remainder is 6.1 − 2.6 = 3.5 eV."}}}},
  {"id":"ch6-stopping-voltage","subject":"physics","chapter_key":"6","display_order":3,"content":{"ar":{"title":"جهد الإيقاف","question":"أقصى طاقة حركية لإلكترون منبعث كهروضوئياً هي 1.8 eV. احسب مقدار جهد الإيقاف.","solution":"درجة لكتابة K_max = e|Vₛ| حيث e مقدار شحنة الإلكترون. درجة لاستخدام وحدة eV مباشرة وإيجاد 1.8 V.","practice":{"question":"إذا كانت أقصى طاقة حركية 3.2 eV، شكد مقدار جهد الإيقاف؟","choices":["0.32 V","5.12 V","3.2 V"],"correctIndex":2,"explanation":"كل إلكترون فولت هو طاقة شحنة إلكترون عبر فولت واحد. نحتاج مقدار جهد 3.2 V حتى نوقف أسرع إلكترون."}},"en":{"title":"Stopping potential","question":"A photoelectron has a maximum kinetic energy of 1.8 eV. Find the magnitude of the stopping potential.","solution":"One mark for K_max = e|Vₛ|, where e is the magnitude of the electron charge. One for using the eV unit to get 1.8 V.","practice":{"question":"If the maximum kinetic energy is 3.2 eV, what is the magnitude of the stopping potential?","choices":["0.32 V","5.12 V","3.2 V"],"correctIndex":2,"explanation":"An electronvolt is the energy for an electron charge across one volt. Stopping the fastest electron requires a potential magnitude of 3.2 V."}}}},
  {"id":"ch6-de-broglie","subject":"physics","chapter_key":"6","display_order":4,"content":{"ar":{"title":"الطول الموجي لدي برولي","question":"صار مقدار زخم جسيم ثلاثة أمثال قيمته الأصلية. شلون يتغيّر طول موجة دي برولي المصاحبة له؟","solution":"درجة لكتابة λ = h/p. درجة لاستنتاج أن الطول الموجي يصير ثلث قيمته عند 3p.","practice":{"question":"إذا نزل مقدار زخم جسيم إلى نصف قيمته، شكد يصير طول موجة دي برولي مقارنة بالأصلي؟","choices":["نصف الأصلي","ضعف الأصلي","نفس الأصلي"],"correctIndex":1,"explanation":"الزخم بالمقام في λ = h/p. من يصير p/2، الطول الموجي يتضاعف."}},"en":{"title":"de Broglie wavelength","question":"A particle’s momentum magnitude triples. What happens to its de Broglie wavelength?","solution":"One mark for λ = h/p. One for concluding that the wavelength is one third as long at 3p.","practice":{"question":"If the particle’s momentum falls to half its original magnitude, what is its new de Broglie wavelength?","choices":["Half the original","Twice the original","The same as before"],"correctIndex":1,"explanation":"Momentum is in the denominator of λ = h/p. Replacing p with p/2 doubles the wavelength."}}}},
  {"id":"ch6-wien","subject":"physics","chapter_key":"6","display_order":5,"content":{"ar":{"title":"إزاحة قمة طيف الجسم الأسود","question":"تضاعفت درجة حرارة جسم أسود مقاسة بالكلفن. شلون يتغيّر الطول الموجي عند قمة طيف إشعاعه بدلالة الطول الموجي؟","solution":"درجة لكتابة قانون فين λ_max T = ثابت. درجة لاستنتاج أن الطول الموجي لقمة الطيف يصير نصفه.","practice":{"question":"إذا ارتفعت درجة حرارة جسم أسود من 1,000 K إلى 3,000 K، شكد يصير الطول الموجي لقمة الطيف مقارنة بقيمته الأولى؟","choices":["ثلث قيمته","ثلاثة أمثال قيمته","نصف قيمته"],"correctIndex":0,"explanation":"بما أن λ_max T ثابت، رفع درجة الحرارة إلى ثلاثة أمثالها يقسّم طول الموجة عند القمة على ثلاثة."}},"en":{"title":"Blackbody peak and Wien’s law","question":"A blackbody’s temperature in kelvins doubles. What happens to the peak wavelength of its wavelength spectrum?","solution":"One mark for Wien’s law λ_max T = constant. One for halving the peak wavelength.","practice":{"question":"A blackbody warms from 1,000 K to 3,000 K. What is the new peak wavelength relative to the original?","choices":["One third","Three times","One half"],"correctIndex":0,"explanation":"Since λ_max T is constant, tripling the absolute temperature divides the peak wavelength by three."}}}},
  {"id":"ch7-doping","subject":"physics","chapter_key":"7","display_order":1,"content":{"ar":{"title":"التطعيم وحوامل الشحنة","question":"طُعّم السيليكون النقي بذرات فسفور خماسية التكافؤ. اذكر نوع شبه الموصل الناتج وحوامل الشحنة الأكثرية.","solution":"درجة للنوع n. درجة لتحديد الإلكترونات حوامل أكثرية لأن الفسفور يمنح إلكتروناً إضافياً قابلاً للتوصيل.","practice":{"question":"إذا طعّمنا السيليكون بالبورون ثلاثي التكافؤ، أي نوع ينتج ومنو حوامل الأكثرية؟","choices":["النوع n والإلكترونات","النوع p والفجوات","النوع p والإلكترونات"],"correctIndex":1,"explanation":"البورون يعمل كمستقبِل. ينتج نوع p وتصير الفجوات هي الحوامل الأكثرية."}},"en":{"title":"Doping and majority carriers","question":"Pure silicon is doped with pentavalent phosphorus atoms. State the resulting semiconductor type and its majority charge carriers.","solution":"One mark for n-type. One for electrons as majority carriers because phosphorus donates an additional electron that can conduct.","practice":{"question":"When silicon is doped with trivalent boron, what type results and what are its majority carriers?","choices":["n-type and electrons","p-type and holes","p-type and electrons"],"correctIndex":1,"explanation":"Boron acts as an acceptor. The silicon becomes p-type, with holes as the majority carriers."}}}},
  {"id":"ch7-band-gap","subject":"physics","chapter_key":"7","display_order":2,"content":{"ar":{"title":"حزم الطاقة في شبه الموصل","question":"في شبه موصل نقي، شنو المقصود بفجوة الطاقة المحرّمة؟ سمِّ الحزمتين اللي تقع بينهن.","solution":"درجة لأنها مدى طاقات لا توجد فيه حالات إلكترونية مسموحة في البلورة النقية. درجة لأنها بين حزمة التكافؤ وحزمة التوصيل.","practice":{"question":"إذا اكتسب إلكترون في حزمة التكافؤ طاقة حرارية كافية لعبور فجوة الطاقة، إلى أي حزمة ينتقل؟","choices":["حزمة التوصيل","يبقى في حزمة التكافؤ","يبقى داخل فجوة الطاقة"],"correctIndex":0,"explanation":"الإلكترون يصعد لحزمة التوصيل ويترك مكانه فجوة في حزمة التكافؤ."}},"en":{"title":"Semiconductor energy bands","question":"In an intrinsic semiconductor, what is the forbidden energy gap? Name the two bands on either side.","solution":"One mark for the range of energies with no allowed electronic states in the ideal pure crystal. One for naming the valence and conduction bands.","practice":{"question":"A valence-band electron gains enough thermal energy to cross the gap. Which band does it enter?","choices":["The conduction band","It stays in the valence band","It stays in the gap"],"correctIndex":0,"explanation":"It moves to the conduction band and leaves a hole behind in the valence band."}}}},
  {"id":"ch7-diode-bias","subject":"physics","chapter_key":"7","display_order":3,"content":{"ar":{"title":"انحياز الوصلة الثنائية","question":"حتى تنحاز الوصلة PN أمامياً، بأي منطقة توصل قطب البطارية الموجب وبأي منطقة توصل السالب؟","solution":"درجة للموجب مع منطقة p. درجة للسالب مع منطقة n.","practice":{"question":"وصلنا الموجب بمنطقة n والسالب بمنطقة p. شنو نوع الانحياز وشنو يصير لعرض منطقة الاستنزاف؟","choices":["أمامي وتتسع","عكسي وتضيق","عكسي وتتسع"],"correctIndex":2,"explanation":"هذا انحياز عكسي. قطبا المصدر يسحبان حوامل الشحنة الأكثرية بعيداً عن الوصلة فتتسع منطقة الاستنزاف."}},"en":{"title":"Diode bias","question":"To forward-bias a PN junction, which region do you connect to the battery’s positive terminal and which to its negative terminal?","solution":"One mark for connecting positive to p. One for connecting negative to n.","practice":{"question":"Positive is connected to n and negative to p. What is the bias, and what happens to the depletion region’s width?","choices":["Forward bias and it widens","Reverse bias and it narrows","Reverse bias and it widens"],"correctIndex":2,"explanation":"This is reverse bias. The applied voltage draws majority carriers away from the junction, widening the depletion region."}}}},
  {"id":"ch7-transistor-currents","subject":"physics","chapter_key":"7","display_order":4,"content":{"ar":{"title":"تيارات الترانزستور","question":"في ترانزستور ثنائي القطبية، مقدار تيار المجمع 2.95 mA ومقدار تيار القاعدة 50 µA. احسب مقدار تيار الباعث.","solution":"درجة لتوحيد الوحدات بتحويل 50 µA إلى 0.050 mA. درجة لاستخدام I_E = I_C + I_B وإيجاد 3.00 mA.","practice":{"question":"مقدار تيار المجمع 4.90 mA ومقدار تيار القاعدة 100 µA. شكد مقدار تيار الباعث؟","choices":["4.80 mA","104.90 mA","5.00 mA"],"correctIndex":2,"explanation":"100 µA تساوي 0.10 mA. نجمع تيار المجمع والقاعدة فنحصل على 5.00 mA."}},"en":{"title":"Transistor currents","question":"In a bipolar transistor, the collector current magnitude is 2.95 mA and the base current magnitude is 50 µA. Find the emitter current magnitude.","solution":"One mark for converting 50 µA to 0.050 mA. One for using I_E = I_C + I_B to get 3.00 mA.","practice":{"question":"Collector and base current magnitudes are 4.90 mA and 100 µA. What is the emitter current magnitude?","choices":["4.80 mA","104.90 mA","5.00 mA"],"correctIndex":2,"explanation":"100 µA equals 0.10 mA. Adding the collector and base currents gives 5.00 mA."}}}},
  {"id":"ch7-current-gain","subject":"physics","chapter_key":"7","display_order":5,"content":{"ar":{"title":"كسب التيار في الباعث المشترك","question":"ترانزستور في المنطقة الفعّالة يمر فيه تيار مجمع 4.0 mA وتيار قاعدة 40 µA. احسب معامل كسب التيار المستمر β.","solution":"درجة لتحويل 40 µA إلى 0.040 mA. درجة لاستخدام β = I_C/I_B وإيجاد 100 بلا وحدة.","practice":{"question":"في المنطقة الفعّالة، إذا كان تيار المجمع 6.0 mA وتيار القاعدة 50 µA، شكد قيمة β؟","choices":["0.12","120","300"],"correctIndex":1,"explanation":"نوحّد الوحدات ونقسم تيار المجمع على تيار القاعدة. β = 6.0 ÷ 0.050 = 120."}},"en":{"title":"Common-emitter current gain","question":"An active-region transistor has collector current 4.0 mA and base current 40 µA. Find the DC current gain β.","solution":"One mark for converting 40 µA to 0.040 mA. One for β = I_C/I_B and a dimensionless gain of 100.","practice":{"question":"In the active region, what is β when the collector current is 6.0 mA and the base current is 50 µA?","choices":["0.12","120","300"],"correctIndex":1,"explanation":"Use consistent units and divide collector current by base current. β = 6.0 ÷ 0.050 = 120."}}}},
  {"id":"ch8-emission-energy","subject":"physics","chapter_key":"8","display_order":1,"content":{"ar":{"title":"طاقة فوتون الانبعاث","question":"انتقل إلكترون في ذرة الهيدروجين من مستوى طاقته سالب 1.51 إلكترون فولت إلى مستوى طاقته سالب 3.40 إلكترون فولت. احسب طاقة الفوتون المنبعث.","solution":"درجة لكتابة طاقة الفوتون = طاقة المستوى الابتدائي − طاقة المستوى النهائي. درجة لحساب 1.89 eV.","practice":{"question":"إلكترون هبط من مستوى طاقته سالب 0.85 إلكترون فولت إلى مستوى طاقته سالب 3.40 إلكترون فولت. شكد طاقة الفوتون المنبعث؟","choices":["−2.55 eV","4.25 eV","2.55 eV"],"correctIndex":2,"explanation":"الفوتون يحمل الطاقة اللي فقدها الإلكترون. نطرح سالب 3.40 من سالب 0.85 فيصير الفرق 2.55 إلكترون فولت."}},"en":{"title":"Emission photon energy","question":"A hydrogen electron drops from an energy level at −1.51 eV to one at −3.40 eV. Find the energy of the emitted photon.","solution":"One mark for photon energy = initial level energy − final level energy. One for 1.89 eV.","practice":{"question":"An electron drops from −0.85 eV to −3.40 eV. What is the emitted photon energy?","choices":["−2.55 eV","4.25 eV","2.55 eV"],"correctIndex":2,"explanation":"The photon carries the energy lost by the electron. Subtract the final energy from the initial energy: −0.85 − (−3.40) = 2.55 eV."}}}},
  {"id":"ch8-hydrogen-series","subject":"physics","chapter_key":"8","display_order":2,"content":{"ar":{"title":"متسلسلات طيف الهيدروجين","question":"انتقل إلكترون الهيدروجين من المستوى n = 4 إلى المستوى n = 1. لأي متسلسلة طيفية ينتمي خط الانبعاث الناتج؟ وضّح السبب.","solution":"درجة لتحديد متسلسلة لايمان. درجة لأن المستوى النهائي هو n = 1.","practice":{"question":"الانتقال من n = 5 إلى n = 2 بذرّة الهيدروجين ينطي خط من أي متسلسلة؟","choices":["بالمر","لايمان","باشن"],"correctIndex":0,"explanation":"نحدّد المتسلسلة من المستوى اللي انتهى عنده الإلكترون. كل انتقال انبعاث إلى n = 2 ينتمي لمتسلسلة بالمر."}},"en":{"title":"Hydrogen spectral series","question":"A hydrogen electron transitions from n = 4 to n = 1. Which spectral series contains the emitted line? Explain why.","solution":"One mark for the Lyman series. One for identifying n = 1 as the final level.","practice":{"question":"Which hydrogen series contains the line from a transition from n = 5 to n = 2?","choices":["Balmer","Lyman","Paschen"],"correctIndex":0,"explanation":"The final level determines the series. Every emission transition ending at n = 2 is in the Balmer series."}}}},
  {"id":"ch8-ionization","subject":"physics","chapter_key":"8","display_order":3,"content":{"ar":{"title":"طاقة التأيّن","question":"إلكترون الهيدروجين موجود في مستوى طاقته سالب 3.40 إلكترون فولت. احسب أقل طاقة لازمة لتأيين الذرّة من هذا المستوى، إذا كان حد التأيّن عند صفر إلكترون فولت.","solution":"درجة لتحديد حد التأيّن عند صفر إلكترون فولت. درجة لطرح سالب 3.40 من الصفر والحصول على 3.40 إلكترون فولت.","practice":{"question":"إذا كانت طاقة المستوى الأرضي للهيدروجين سالب 13.6 إلكترون فولت، شكد أقل طاقة لازم نطيها حتى نأيّن الذرّة من هذا المستوى؟","choices":["3.4 eV","13.6 eV","−13.6 eV"],"correctIndex":1,"explanation":"حتى يطلع الإلكترون من الذرّة لازم يوصل من سالب 13.6 إلكترون فولت إلى حد التأيّن عند الصفر. يحتاج يمتص 13.6 إلكترون فولت."}},"en":{"title":"Ionization energy","question":"A hydrogen electron is in a level at −3.40 eV. What is the minimum energy needed to ionize it from this level if the ionization limit is 0 eV?","solution":"One mark for recognizing the free-electron threshold at 0 eV. One for 0 − (−3.40) = 3.40 eV.","practice":{"question":"The hydrogen ground state is at −13.6 eV. How much energy is needed to ionize it from that state?","choices":["3.4 eV","13.6 eV","−13.6 eV"],"correctIndex":1,"explanation":"To leave the atom the electron must reach 0 eV from −13.6 eV. It must absorb 13.6 eV."}}}},
  {"id":"ch8-stimulated-emission","subject":"physics","chapter_key":"8","display_order":4,"content":{"ar":{"title":"الانبعاث المستحث","question":"تفاعل فوتون طاقته توافق فرق مستويين مع ذرّة مثارة، وحفّزها للهبوط وانبعاث فوتون. شنو اسم العملية وشلون يقارن تردد الفوتونين؟","solution":"درجة للانبعاث المستحث. درجة لأن الفوتون المنبعث له نفس تردد الفوتون المحفِّز.","practice":{"question":"بالانبعاث المستحث في نمط الليزر، شنو العلاقة بين الفوتون المنبعث والفوتون المحفِّز؟","choices":["تردد مختلف واتجاه عشوائي","نفس التردد وطور عشوائي","نفس التردد والطور والاتجاه"],"correctIndex":2,"explanation":"الانبعاث المستحث يضيف ضوءاً متوافقاً ويّا الضوء المحفِّز في التردد والطور والاتجاه."}},"en":{"title":"Stimulated emission","question":"A photon matching the energy gap interacts with an excited atom and stimulates it to drop and emit a photon. Name the process and compare the two photon frequencies.","solution":"One mark for stimulated emission. One for the emitted photon having the same frequency as the stimulating photon.","practice":{"question":"In stimulated emission into the laser mode, how does the emitted photon compare with the stimulating photon?","choices":["Different frequency and random direction","Same frequency but random phase","Same frequency, phase, and direction"],"correctIndex":2,"explanation":"Stimulated emission adds light that matches the stimulating light in frequency, phase, and direction."}}}},
  {"id":"ch8-population-inversion","subject":"physics","chapter_key":"8","display_order":5,"content":{"ar":{"title":"الضخ والانقلاب السكاني","question":"شنو دور الضخ في الوسط الفعّال لليزر؟ اشرح شلون يرتبط بانقلاب الإشغال بين مستويي الانتقال.","solution":"درجة لتزويد الوسط الفعّال بالطاقة ورفع ذرات إلى مستويات أعلى. درجة لأن الضخ يمكن أن يجعل عدد الذرات بالمستوى العلوي للانتقال أكبر من السفلي.","practice":{"question":"من نقارن عدد الذرات بمستويي انتقال الليزر، أي حالة تبيّن حصول انقلاب سكاني؟","choices":["عدد الذرات بالعلوي أكبر","عدد الذرات بالسفلي أكبر","العددان متساويان"],"correctIndex":0,"explanation":"الضخ يگدر يخلّي إشغال المستوى العلوي أكبر من السفلي، وهي حالة الانقلاب السكاني."}},"en":{"title":"Pumping and population inversion","question":"What does pumping do in a laser’s active medium? Explain its role in creating an inversion between the two laser transition levels.","solution":"One mark for supplying energy to promote atoms to higher levels. One for raising the upper laser level’s population above the lower level’s population.","practice":{"question":"When comparing the populations of the two laser transition levels, which condition indicates a population inversion?","choices":["More atoms in the upper level","More atoms in the lower level","Equal populations"],"correctIndex":0,"explanation":"Pumping can make the upper laser level more populated than the lower one. That is population inversion."}}}},
  {"id":"chemistry-ph-strong-acid","subject":"chemistry","chapter_key":"3","display_order":1,"content":{"ar":{"title":"الرقم الهيدروجيني لحمض قوي","question":"احسب pH لمحلول HCl تركيزه 0.001 mol/L. افترض التأين التام وأهمل التأين الذاتي للماء.","solution":"بالتأين التام، تركيز H₃O⁺ يساوي 10⁻³ mol/L. من pH = −log₁₀[H₃O⁺] نحصل على 3.","practice":{"question":"ما pH لمحلول HCl تركيزه 10⁻⁴ mol/L مع نفس الافتراضات؟","choices":["4","10","1"],"correctIndex":0,"explanation":"تركيز H₃O⁺ يساوي 10⁻⁴ mol/L. اللوغاريتم سالب أربعة، فـ pH يساوي 4."}},"en":{"title":"pH of a strong acid","question":"Calculate the pH of 0.001 mol/L HCl. Assume complete dissociation and ignore the self-ionization of water.","solution":"Complete dissociation gives [H₃O⁺] = 10⁻³ mol/L. Therefore pH = −log₁₀[H₃O⁺] = 3.","practice":{"question":"What is the pH of 10⁻⁴ mol/L HCl under the same assumptions?","choices":["4","10","1"],"correctIndex":0,"explanation":"The hydronium concentration is 10⁻⁴ mol/L, so its negative base-ten logarithm is 4."}}}},
  {"id":"biology-nucleus","subject":"biology","chapter_key":"1","display_order":1,"content":{"ar":{"title":"النواة والمادة الوراثية","question":"ما التركيب الذي يحوي معظم المادة الوراثية في الخلية الحيوانية النموذجية؟ وضّح وظيفته.","solution":"النواة تحوي معظم DNA الخلية. تنظيم التعبير عن الجينات يساعد النواة في التحكم بأنشطة الخلية.","practice":{"question":"أين توجد معظم جينات الخلية الحيوانية داخل النواة؟","choices":["في السيتوبلازم","على الكروموسومات","على الغشاء النووي"],"correctIndex":1,"explanation":"الجينات أجزاء من DNA، ومعظم DNA الخلية مرتّب ضمن كروموسومات النواة."}},"en":{"title":"Nucleus and genetic material","question":"Which structure contains most of the genetic material of a typical animal cell? Explain its role.","solution":"The nucleus contains most of the cell's DNA. It helps control cell activities through regulation of gene expression.","practice":{"question":"Where are most of an animal cell’s genes located within the nucleus?","choices":["In the cytoplasm","On the chromosomes","On the nuclear membrane"],"correctIndex":1,"explanation":"Genes are sections of DNA. Most of the cell’s DNA is organized into chromosomes in the nucleus."}}}},
  {"id":"english-ed-ing-adjectives","subject":"english","chapter_key":"1","display_order":1,"content":{"ar":{"title":"الصفات المنتهية بـ ed وing","question":"I felt (bored / boring) during the film. Choose the correct adjective and explain your choice.","solution":"الاختيار bored لأن المتكلم يصف شعوره. Boring تصف الشيء الذي يسبب الشعور بالملل.","practice":{"question":"Complete the sentence with an adjective that describes the lesson. The lesson was ____.","choices":["excited","excite","exciting"],"correctIndex":2,"explanation":"نختار exciting لأن الجملة تصف الدرس الذي سبّب الشعور بالحماس. Excited تصف الشخص الذي شعر بالحماس."}},"en":{"title":"Adjectives ending in -ed and -ing","question":"I felt (bored / boring) during the film. Choose the correct adjective and explain your choice.","solution":"Bored describes how the speaker felt. Boring would describe what caused that feeling.","practice":{"question":"Complete the sentence with an adjective that describes the lesson. The lesson was ____.","choices":["excited","excite","exciting"],"correctIndex":2,"explanation":"Exciting describes the lesson that caused excitement. Excited describes the person who felt it."}}}},
  {"id":"french-negation-present","subject":"french","chapter_key":"negation","display_order":1,"content":{"ar":{"title":"النفي بـ ne … pas","question":"Mets à la forme négative la phrase « Il aime le sport. »","solution":"Il n’aime pas le sport. نضع n’ قبل aime لأنها تبدأ بحرف صوتي، ونضع pas بعدها.","practice":{"question":"Mets à la forme négative la phrase « Elle parle français. »","choices":["Elle parle pas ne français.","Elle ne parle pas français.","Elle pas parle français."],"correctIndex":1,"explanation":"بهذه الجملة نضع ne قبل الفعل المصرف parle وpas بعده."}},"en":{"title":"Negation with ne … pas","question":"Mets à la forme négative la phrase « Il aime le sport. »","solution":"Il n’aime pas le sport. Put n’ before aime because it starts with a vowel and put pas after the verb.","practice":{"question":"Mets à la forme négative la phrase « Elle parle français. »","choices":["Elle parle pas ne français.","Elle ne parle pas français.","Elle pas parle français."],"correctIndex":1,"explanation":"Place ne before the conjugated verb parle and pas after it."}}}},
  {"id":"arabic-interrogation-type","subject":"arabic","chapter_key":"ar-istifham","display_order":1,"content":{"ar":{"title":"التصديق والتصوّر","question":"«هل قرأتَ الدرس؟» حدّد أداة الاستفهام ونوعه من حيث الجواب.","solution":"الأداة هل، والاستفهام للتصديق لأن الجواب يكون بنعم أو لا.","practice":{"question":"في سؤال «أين كتابك؟»، ما نوع الاستفهام من حيث الجواب؟","choices":["تصوّر","تصديق","نفي"],"correctIndex":0,"explanation":"السؤال يطلب تعيين مكان الكتاب، لذلك استفهام تصوّر."}},"en":{"title":"Types of interrogation","question":"«هل قرأتَ الدرس؟» حدّد أداة الاستفهام ونوعه من حيث الجواب.","solution":"The interrogative particle is هل. It asks for a yes-or-no answer, which is استفهام التصديق.","practice":{"question":"What type of answer is requested by «أين كتابك؟»?","choices":["تصوّر","تصديق","نفي"],"correctIndex":0,"explanation":"The question asks the reader to identify a location. This is استفهام التصوّر."}}}},
  {"id":"islamic-iqlab","subject":"islamic","chapter_key":"recitation","display_order":1,"content":{"ar":{"title":"الإقلاب","question":"ما حكم النون الساكنة إذا جاء بعدها حرف الباء؟ اذكر كيف تُقرأ عند الوصل.","solution":"الإقلاب. تُقلب النون الساكنة ميماً مخفاة مع الغنة عند النطق قبل الباء.","practice":{"question":"ما الحرف الذي يوجب الإقلاب إذا جاء بعد التنوين عند الوصل؟","choices":["الميم","اللام","الباء"],"correctIndex":2,"explanation":"الباء حرف الإقلاب. إذا جاء بعد النون الساكنة أو التنوين عند الوصل، يُنطق الحكم بغنة."}},"en":{"title":"Iqlab in recitation","question":"ما حكم النون الساكنة إذا جاء بعدها حرف الباء؟ اذكر كيف تُقرأ عند الوصل.","solution":"The rule is iqlab. Before bāʾ, the silent nūn is pronounced as a concealed mīm with nasalization.","practice":{"question":"Which letter triggers iqlab when it follows tanwīn in connected recitation?","choices":["الميم","اللام","الباء"],"correctIndex":2,"explanation":"Bāʾ is the letter for iqlab after a silent nūn or tanwīn in connected recitation."}}}},
  {"id":"math-complex-addition","subject":"math","chapter_key":"1","display_order":1,"content":{"ar":{"title":"جمع الأعداد المركبة","question":"اجمع العددين (3 + 2i) و(4 − 5i).","solution":"نجمع الجزءين الحقيقيين والجزءين التخيليين كلٌ على حدة. (3 + 4) + (2 − 5)i = 7 − 3i.","practice":{"question":"شنو ناتج جمع (−2 + 4i) و(5 + 3i)؟","choices":["3 + i","3 + 7i","7 + 3i"],"correctIndex":1,"explanation":"للحقيقي نحسب 5 − 2 = 3. وللتخيلي نجمع 4 + 3 = 7، فيطلع الناتج 3 + 7i."}},"en":{"title":"Adding complex numbers","question":"Add the complex numbers (3 + 2i) and (4 − 5i).","solution":"Add real parts and imaginary parts separately. (3 + 4) + (2 − 5)i = 7 − 3i.","practice":{"question":"What is the sum of (−2 + 4i) and (5 + 3i)?","choices":["3 + i","3 + 7i","7 + 3i"],"correctIndex":1,"explanation":"The real part is 5 − 2 = 3 and the imaginary coefficient is 4 + 3 = 7. The sum is 3 + 7i."}}}}
]$paper_exercise_seed$::jsonb) AS s(id text, subject text, chapter_key text, content jsonb, display_order integer)
ON CONFLICT (id) DO NOTHING;
